using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;
public static class StartReverseChecks{public static string Main(){if(Application.isPlaying||EditorApplication.isCompiling)throw new Exception("Compiled edit mode required");EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");if(UnityEngine.Object.FindObjectsByType<BackyardReverseChecks>().Length!=0)throw new Exception("No saved test fixture allowed");File.WriteAllText("Temp/backyardreverse-editor-options.txt",EditorSettings.enterPlayModeOptionsEnabled.ToString());EditorSettings.enterPlayModeOptionsEnabled=true;EditorSettings.enterPlayModeOptions=EnterPlayModeOptions.DisableDomainReload;AudioListener.volume=0;
void Changed(PlayModeStateChange state){if(state!=PlayModeStateChange.EnteredPlayMode)return;EditorApplication.playModeStateChanged-=Changed;EditorApplication.delayCall+=()=>BackyardReverseChecks.Launch();}
EditorApplication.playModeStateChanged+=Changed;EditorApplication.delayCall+=()=>EditorApplication.isPlaying=true;return "Enter play with saved scene, then add exactly one isolated Reverse fixture";}}
